# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def numComponents(self, head: Optional[ListNode], nums: List[int]) -> int:
        def contains(v):
            for x in nums:
                if x == v:
                    return True
            return False
        count, prevIn = 0, False
        cur = head
        while cur:
            curIn = contains(cur.val)
            if curIn and not prevIn:
                count += 1
            prevIn = curIn
            cur = cur.next
        return count

